-- DigiArz disposable PostgreSQL 17 RPC-security fixture.
-- TEST-ONLY: synthetic roles, identities, schemas, and empty reporting tables.
-- No Supabase project, production secret, user, wallet, order, or live data is used.
-- This fixture models one read-only admin RPC path only; it is NOT a complete
-- Production-parity clone and must never be used as one.

\set ON_ERROR_STOP on

DO $roles$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    CREATE ROLE anon NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    CREATE ROLE authenticated NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    CREATE ROLE service_role NOLOGIN BYPASSRLS;
  END IF;
END
$roles$;

CREATE SCHEMA IF NOT EXISTS auth;
CREATE SCHEMA IF NOT EXISTS private;

CREATE TABLE private.admin_users (
  user_id uuid PRIMARY KEY,
  role text NOT NULL,
  granted_at timestamptz NOT NULL DEFAULT now(),
  granted_by uuid
);

INSERT INTO private.admin_users (user_id, role)
VALUES ('22222222-2222-4222-8222-222222222222', 'super_admin');

CREATE TABLE public.exchange_asset_observations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  exchange text NOT NULL,
  market_symbol text NOT NULL,
  base_symbol text,
  quote_symbol text,
  asset_name text,
  coingecko_id text,
  match_status text NOT NULL,
  source_url text NOT NULL,
  source_payload jsonb,
  is_active boolean NOT NULL DEFAULT true,
  first_seen_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.admin_market_listings (
  coingecko_id text PRIMARY KEY,
  added_by uuid,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.exchange_asset_sync_requests (
  request_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  exchange text NOT NULL,
  requested_at timestamptz NOT NULL DEFAULT now(),
  processed_at timestamptz,
  http_status integer,
  error_message text
);

CREATE TABLE public.bit24_exchange_sync_requests (
  request_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  requested_at timestamptz NOT NULL DEFAULT now(),
  processed_at timestamptz,
  http_status integer,
  error_message text
);

-- Minimal test shim, not a Supabase Auth implementation or JWT verifier.
CREATE OR REPLACE FUNCTION auth.uid()
RETURNS uuid
LANGUAGE sql
STABLE
SET search_path = ''
AS $function$
  SELECT NULLIF(current_setting('request.jwt.claim.sub', true), '')::uuid;
$function$;

CREATE OR REPLACE FUNCTION private.is_super_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM private.admin_users a
    WHERE a.user_id = (SELECT auth.uid())
      AND a.role = 'super_admin'
  );
$function$;

CREATE OR REPLACE FUNCTION private.is_current_user_super_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $function$
  SELECT (SELECT auth.uid()) IS NOT NULL
     AND private.is_super_admin();
$function$;

-- Exact current Production function body, read through pg_get_functiondef
-- on 2026-11-25. Reporting tables above are empty and synthetic.
CREATE OR REPLACE FUNCTION public.admin_exchange_asset_sync_report()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
  result jsonb;
BEGIN
  IF NOT private.is_current_user_super_admin() THEN
    RAISE EXCEPTION 'دسترسی مدیر ارشد لازم است' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'summary', jsonb_build_object(
      'observations', (SELECT count(*) FROM public.exchange_asset_observations),
      'exchanges', (SELECT count(DISTINCT exchange) FROM public.exchange_asset_observations WHERE is_active),
      'symbols', (SELECT count(DISTINCT base_symbol) FROM public.exchange_asset_observations WHERE is_active),
      'matched', (SELECT count(*) FROM public.exchange_asset_observations WHERE is_active AND match_status='matched'),
      'ambiguous', (SELECT count(*) FROM public.exchange_asset_observations WHERE is_active AND match_status='ambiguous'),
      'pending', (SELECT count(*) FROM public.exchange_asset_observations WHERE is_active AND match_status='pending'),
      'unmatched', (SELECT count(*) FROM public.exchange_asset_observations WHERE is_active AND match_status='unmatched'),
      'listed', (SELECT count(*) FROM public.admin_market_listings)
    ),
    'sources', (
      SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.exchange), '[]'::jsonb)
      FROM (
        SELECT e.exchange,
          coalesce(o.active_markets,0) AS active_markets,
          o.last_seen_at,
          r.last_requested_at,
          r.last_processed_at,
          r.http_status,
          r.error_message
        FROM (VALUES ('nobitex'),('wallex'),('tabdeal'),('ompfinex'),('exir'),('abantether'),('bit24')) e(exchange)
        LEFT JOIN LATERAL (
          SELECT count(*) FILTER(WHERE is_active) AS active_markets, max(last_seen_at) AS last_seen_at
          FROM public.exchange_asset_observations x WHERE x.exchange=e.exchange
        ) o ON true
        LEFT JOIN LATERAL (
          SELECT max(requested_at) AS last_requested_at, max(processed_at) AS last_processed_at,
            (array_agg(http_status ORDER BY requested_at DESC))[1] AS http_status,
            (array_agg(error_message ORDER BY requested_at DESC))[1] AS error_message
          FROM (
            SELECT requested_at, processed_at, http_status, error_message
            FROM public.exchange_asset_sync_requests WHERE exchange=e.exchange
            UNION ALL
            SELECT requested_at, processed_at, http_status, error_message
            FROM public.bit24_exchange_sync_requests WHERE e.exchange='bit24'
          ) z
        ) r ON true
      ) s
    ),
    'issues', (
      SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.exchange, i.base_symbol), '[]'::jsonb)
      FROM (
        SELECT exchange, base_symbol, asset_name, market_symbol, match_status, coingecko_id, last_seen_at
        FROM public.exchange_asset_observations
        WHERE is_active AND match_status IN ('ambiguous','pending','unmatched')
        ORDER BY CASE match_status WHEN 'ambiguous' THEN 1 WHEN 'pending' THEN 2 ELSE 3 END, last_seen_at DESC
        LIMIT 100
      ) i
    )
  ) INTO result;

  RETURN result;
END;
$function$;

REVOKE ALL ON FUNCTION public.admin_exchange_asset_sync_report() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.admin_exchange_asset_sync_report() FROM anon;
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_exchange_asset_sync_report() TO authenticated, service_role;
REVOKE ALL ON SCHEMA private FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON TABLE private.admin_users FROM PUBLIC, anon, authenticated, service_role;


-- Exact Production function body recovered from migration
-- 20261113190000_admin_on_demand_crypto_asset_refresh.sql.
-- The only row/data dependency is a synthetic private table in this fixture.
CREATE TABLE private.admin_asset_refresh_limits (
  coingecko_id text PRIMARY KEY,
  last_requested_at timestamptz NOT NULL,
  requested_by uuid NOT NULL
);
ALTER TABLE private.admin_asset_refresh_limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE private.admin_asset_refresh_limits FROM PUBLIC, anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.claim_admin_asset_refresh(
  p_coingecko_id text,
  p_admin_user_id uuid
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
  v_claimed boolean := false;
BEGIN
  IF p_admin_user_id IS NULL
     OR p_coingecko_id IS NULL
     OR pg_catalog.length(pg_catalog.btrim(p_coingecko_id)) NOT BETWEEN 1 AND 128 THEN
    RAISE EXCEPTION 'Invalid refresh request' USING errcode = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM private.admin_users a
    WHERE a.user_id = p_admin_user_id
      AND a.role = 'super_admin'
  ) THEN
    RAISE EXCEPTION 'Super administrator access required' USING errcode = '42501';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    742021,
    pg_catalog.hashtext(pg_catalog.btrim(p_coingecko_id))
  );

  INSERT INTO private.admin_asset_refresh_limits(
    coingecko_id, last_requested_at, requested_by
  )
  VALUES (pg_catalog.btrim(p_coingecko_id), pg_catalog.now(), p_admin_user_id)
  ON CONFLICT (coingecko_id) DO UPDATE
    SET last_requested_at = EXCLUDED.last_requested_at,
        requested_by = EXCLUDED.requested_by
    WHERE private.admin_asset_refresh_limits.last_requested_at
          <= pg_catalog.now() - interval '30 seconds'
  RETURNING true INTO v_claimed;

  IF NOT COALESCE(v_claimed, false) THEN
    RAISE EXCEPTION 'This asset was refreshed recently; wait 30 seconds'
      USING errcode = '55000';
  END IF;

  RETURN true;
END;
$function$;

REVOKE ALL ON FUNCTION public.claim_admin_asset_refresh(text, uuid) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.claim_admin_asset_refresh(text, uuid) TO service_role;


