-- Exact read-only function body from the final reviewed migration source.
CREATE OR REPLACE FUNCTION public.get_admin_market_listings()
RETURNS TABLE (
  coingecko_id text,
  symbol text,
  name text,
  image_url text,
  market_cap_rank integer,
  current_price_usd numeric,
  price_toman numeric,
  price_change_percentage_24h numeric,
  total_volume_usd numeric,
  last_updated timestamptz,
  added_at timestamptz
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $function$
  SELECT
    ca.coingecko_id,
    ca.symbol,
    ca.name,
    ca.image_url,
    ca.market_cap_rank,
    CASE
      WHEN mp.updated_at >= pg_catalog.now() - interval '2 minutes'
       AND mp.source = 'CoinGecko'
       AND mp.price > 0
      THEN mp.price
      ELSE NULL
    END AS current_price_usd,
    ca.price_toman,
    ca.price_change_percentage_24h,
    ca.total_volume_usd,
    mp.updated_at AS last_updated,
    l.created_at AS added_at
  FROM public.admin_market_listings AS l
  JOIN public.crypto_assets AS ca ON ca.coingecko_id = l.coingecko_id
  LEFT JOIN public.market_prices AS mp
    ON mp.symbol = pg_catalog.upper(ca.symbol) || 'USDT'
  WHERE ca.is_active IS TRUE
  ORDER BY l.created_at DESC, ca.market_cap_rank ASC NULLS LAST;
$function$;

-- Match the reviewed current effective ACL in the disposable fixture.
-- The service_role grant here models the observed function ACL only; it does
-- not set or alter any default privileges.
REVOKE ALL ON FUNCTION public.get_admin_market_listings() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_admin_market_listings() TO anon, authenticated, service_role;

-- Source-backed read-only exchange-discovery RPC from
-- 20261116200009_auto_list_unmatched_iran_exchange_assets.sql.
CREATE OR REPLACE FUNCTION public.get_exchange_discovered_market_assets()
RETURNS TABLE (
  symbol text,
  name text,
  current_price_usd numeric,
  last_updated timestamptz,
  exchange_sources text,
  exchange_count integer,
  observed_at timestamptz,
  match_status text
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $function$
  WITH active_observations AS (
    SELECT upper(o.base_symbol) AS symbol,
           nullif(btrim(o.asset_name), '') AS asset_name,
           o.exchange, o.last_seen_at, o.match_status
    FROM public.exchange_asset_observations AS o
    WHERE o.is_active IS TRUE
      AND o.base_symbol ~ '^[A-Z0-9]{2,20}'
      AND o.base_symbol !~ '[^A-Z0-9]'
      AND pg_catalog.length(o.base_symbol) BETWEEN 2 AND 20
      AND o.last_seen_at >= pg_catalog.now() - interval '48 hours'
      AND o.match_status IN ('pending', 'ambiguous', 'unmatched')
      AND coalesce(o.asset_name, '') !~* '(stock|equity|shares|xstock|tokenized)'
      AND NOT EXISTS (
        SELECT 1
        FROM public.admin_market_listings AS l
        JOIN public.crypto_assets AS ca ON ca.coingecko_id = l.coingecko_id
        WHERE upper(ca.symbol) = upper(o.base_symbol)
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.demo_trading_pairs AS dp
        JOIN public.crypto_assets AS ca ON ca.coingecko_id = dp.base_coingecko_id
        WHERE upper(ca.symbol) = upper(o.base_symbol)
          AND dp.is_enabled IS TRUE
      )
  ),
  grouped AS (
    SELECT symbol,
           (array_agg(asset_name ORDER BY last_seen_at DESC)
             FILTER (WHERE asset_name IS NOT NULL))[1] AS name,
           array_to_string(array_agg(DISTINCT exchange ORDER BY exchange), ', ') AS exchange_sources,
           count(DISTINCT exchange)::integer AS exchange_count,
           max(last_seen_at) AS observed_at,
           CASE WHEN bool_or(match_status = 'ambiguous') THEN 'ambiguous' ELSE 'unmatched' END AS match_status
    FROM active_observations
    GROUP BY symbol
  )
  SELECT g.symbol,
         coalesce(g.name, g.symbol) AS name,
         mp.price AS current_price_usd,
         mp.updated_at AS last_updated,
         g.exchange_sources,
         g.exchange_count,
         g.observed_at,
         g.match_status
  FROM grouped AS g
  LEFT JOIN public.market_prices AS mp
    ON mp.symbol = g.symbol || 'USDT'
   AND mp.price > 0
   AND mp.updated_at >= pg_catalog.now() - interval '2 minutes'
  ORDER BY g.observed_at DESC, g.symbol;
$function$;

-- Match the reviewed effective API-role ACL snapshot in this disposable
-- fixture. The migration itself explicitly grants anon/authenticated; the
-- observed service_role bit is reproduced here without changing defaults.
REVOKE ALL ON FUNCTION public.get_exchange_discovered_market_assets() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_exchange_discovered_market_assets() TO anon, authenticated, service_role;

      AND o.last_seen_at >= pg_catalog.now() - interval '48 hours'
      AND o.match_status IN ('pending', 'ambiguous', 'unmatched')
      AND coalesce(o.asset_name, '') !~* '(stock|equity|shares|xstock|tokenized)'
      AND NOT EXISTS (
        SELECT 1
        FROM public.admin_market_listings AS l
        JOIN public.crypto_assets AS ca ON ca.coingecko_id = l.coingecko_id
        WHERE upper(ca.symbol) = upper(o.base_symbol)
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.demo_trading_pairs AS dp
        JOIN public.crypto_assets AS ca ON ca.coingecko_id = dp.base_coingecko_id
        WHERE upper(ca.symbol) = upper(o.base_symbol)
          AND dp.is_enabled IS TRUE
      )
  ),
  grouped AS (
    SELECT symbol,
           (array_agg(asset_name ORDER BY last_seen_at DESC)
             FILTER (WHERE asset_name IS NOT NULL))[1] AS name,
           array_to_string(array_agg(DISTINCT exchange ORDER BY exchange), ', ') AS exchange_sources,
           count(DISTINCT exchange)::integer AS exchange_count,
           max(last_seen_at) AS observed_at,
           CASE WHEN bool_or(match_status = 'ambiguous') THEN 'ambiguous' ELSE 'unmatched' END AS match_status
    FROM active_observations
    GROUP BY symbol
  )
  SELECT g.symbol,
         coalesce(g.name, g.symbol) AS name,
         mp.price AS current_price_usd,
         mp.updated_at AS last_updated,
         g.exchange_sources,
         g.exchange_count,
         g.observed_at,
         g.match_status
  FROM grouped AS g
  LEFT JOIN public.market_prices AS mp
    ON mp.symbol = g.symbol || 'USDT'
   AND mp.price > 0
   AND mp.updated_at >= pg_catalog.now() - interval '2 minutes'
  ORDER BY g.observed_at DESC, g.symbol;
$function$;

-- Match the reviewed effective API-role ACL snapshot in this disposable
-- fixture. The migration itself explicitly grants anon/authenticated; the
-- observed service_role bit is reproduced here without changing defaults.
REVOKE ALL ON FUNCTION public.get_exchange_discovered_market_assets() FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_exchange_discovered_market_assets() TO anon, authenticated, service_role;
